func TestParsePort(t *testing.T) {
	cases := []struct {
		name    string
		in      string
		want    int
		wantErr error
	}{
		{"valid", "8080", 8080, nil},
		{"spasi di tepi", "  443 ", 443, nil},
		{"batas bawah", "1", 1, nil},
		{"batas atas", "65535", 65535, nil},
		{"kosong", "", 0, ErrEmpty},
		{"hanya spasi", "   ", 0, ErrEmpty},
		{"huruf", "abc", 0, ErrNotNumber},
		{"campuran", "80a", 0, ErrNotNumber},
		{"nol", "0", 0, ErrOutOfRange},
		{"terlalu besar", "70000", 0, ErrOutOfRange},
		{"negatif", "-1", 0, ErrOutOfRange},
	}
	for _, c := range cases {
		t.Run(c.name, func(t *testing.T) {
			got, err := ParsePort(c.in)
			if c.wantErr == nil {
				if err != nil {
					t.Fatalf("ParsePort(%q) error = %v, want nil", c.in, err)
				}
				if got != c.want {
					t.Fatalf("ParsePort(%q) = %d, want %d", c.in, got, c.want)
				}
				return
			}
			if !errors.Is(err, c.wantErr) {
				t.Fatalf("ParsePort(%q) error = %v, want errors.Is(err, %v)", c.in, err, c.wantErr)
			}
			if got != 0 {
				t.Errorf("ParsePort(%q) = %d on error, want 0", c.in, got)
			}
			if in := strings.TrimSpace(c.in); !strings.Contains(err.Error(), in) {
				t.Errorf("error %q should mention input %q", err.Error(), in)
			}
		})
	}
}

