package port

import (
	"errors"
	"fmt"
	"strconv"
	"strings"
)

var (
	ErrEmpty      = errors.New("port kosong")
	ErrNotNumber  = errors.New("port bukan angka")
	ErrOutOfRange = errors.New("port di luar rentang 1-65535")
)

func ParsePort(s string) (int, error) {
	s = strings.TrimSpace(s)
	if s == "" {
		return 0, ErrEmpty
	}
	n, err := strconv.Atoi(s)
	if err != nil {
		return 0, fmt.Errorf("parse port %q: %w", s, ErrNotNumber)
	}
	if n < 1 || n > 65535 {
		return 0, fmt.Errorf("parse port %q: %w", s, ErrOutOfRange)
	}
	return n, nil
}
